package com.paisatrack.modules.attachment;

/**
 * Where attachment bytes live. Keys are generated by the app ({@code userId/attachmentId}), never
 * taken from user input. Swap the implementation (e.g. object storage) without touching callers.
 */
public interface AttachmentStorage {

    void put(String key, byte[] content);

    byte[] get(String key);

    void delete(String key);
}
